def sync(sourcedir=None, exclude_gitignore_entries=None, exclude_regex_list=None):
    """ Create and populate workdir.options.path, memoized so that it only runs once """
    if not sourcedir:
        sourcedir = os.getcwd()
    if not exclude_gitignore_entries:
        exclude_gitignore_entries = []
    if not exclude_regex_list:
        exclude_regex_list = []
    workdir = Workdir(sourcedir, exclude_gitignore_entries, exclude_regex_list)
    return workdir.options.path

