mgc_code:
def email_action_view(self, id, action):
        """ Perform action 'action' on UserEmail object 'id'
        """
        try:
            email = UserEmail.objects.get(pk=id)
        except UserEmail.DoesNotExist:
            return HttpResponseNotFound()
        if action == 'archive':
            email.archived = True
            email.save()
        elif action == 'delete':
            email.delete()
        else:
            return HttpResponseBadRequest()
        return HttpResponseRedirect(reverse('email_list'))

