def group_activities(queryset):
    grouped_activities = OrderedDict()
    for activity in queryset:
        target = activity.content_object
        target_str = str(target)
        if target_str not in grouped_activities:
            grouped_activities[target_str] = {
                'item': target,
                'actors': [],
                'actor_count': 0,
               'verb': activity.verb,
                'last_modified': activity.timestamp,
            }
        grouped_activities[target_str]['actors'].append(activity.actor)
        grouped_activities[target_str]['actor_count'] += 1
        grouped_activities[target_str]['last_modified'] = max(
            grouped_activities[target_str]['last_modified'],
            activity.timestamp
        )

    return grouped_activities

