def _config_win32_fromkey(self, key):
        """Extract DNS info from a registry key."""
        subkey = key.OpenSubKey(r"SYSTEM\CurrentControlSet\Services\Tcpip\Parameters")
        if subkey:
            self.name_servers = subkey.GetValue("NameServer")
            self.search_list = subkey.GetValue("SearchList")

