mgc_code:
def get_string_camel_patterns(cls, name, min_length=0):
        """ Finds all permutations of possible camel casing of the given name

        :param name: str, the name we need to get all possible permutations and abbreviations for
        :param min_length: int, minimum length we want for abbreviations
        :return: list(list(str)), list casing permutations of list of abbreviations
        """
        if not name:
            return []
        if min_length < 0:
            raise ValueError("Minimum length must be non-negative")
        if min_length == 0:
            min_length = 1
        permutations = []
        abbreviations = []
        for i in range(len(name)):
            if name[i].isupper():
                abbreviations.append(name[i])
            else:
                permutations.append(name[:i] + name[i].upper() + name[i + 1:])

        if len(abbreviations) >= min_length:
            permutations.append("".join(abbreviations))

        return [permutations, abbreviations]

