def build(cls: Type[T], data: Generic) -> T:
        """Build objects from dictionaries, recursively."""
        fields = fields_dict(cls)
        kwargs: Dict[str, Any] = {}
        for key, value in data.items():
            if key in fields:
                if isinstance(value, Mapping):
                    t = fields[key].type
                    if issubclass(t, Auto):
                        value = t.build(value)
                    else:
                        value = Auto.generate(value, name=key.title())
                kwargs[key] = value
            else:
                log.debug(f"got unknown attribute {key} for {cls.__name__}")
        return cls(**kwargs)

mgc_code:
def build(cls: Type[T], data: Generic) -> T:
        """Build objects from dictionaries, recursively."""
        if isinstance(data, dict):
            obj = cls()
            for key, value in data.items():
                setattr(obj, key, build(cls, value))
            return obj
        elif isinstance(data, list):
            return [build(cls, item) for item in data]
        else:
            return data

