def lines_from_stream(chunks):
    """
    Given data in chunks, yield lines of text
    """
    buf = buffer.DecodingLineBuffer()
    for chunk in chunks:
        buf.feed(chunk)
        # when Python 3, yield from buf
        for _ in buf:
            yield _

mgc_code:
def lines_from_stream(chunks):
    """
    Given data in chunks, yield lines of text
    """
    line = ''
    for chunk in chunks:
        line += chunk
        if '\n' in line:
            lines = line.split('\n')
            for i in range(len(lines) - 1):
                yield lines[i]
            line = lines[-1]
    if line:
        yield line

