        """
        :param timeout: OPTIONAL DURATION
        :return: None, IF timeout PASSES
        """
        if timeout is None:
            return self._queue.pop()
        else:
            try:
                return self._queue.pop(timeout=timeout)
            except IndexError:
                return None

