def intersectingPoint(self, p):
    """
    given a point, get intervals in the tree that are intersected.

    :param p: intersection point
    :return: the list of intersected intervals
    """
    result = []
    def dfs(node):
        if not node:
            return
        if node.start <= p <= node.end:
            result.append(node)
        if node.left and node.left.end >= p:
            dfs(node.left)
        if node.right and node.right.start <= p:
            dfs(node.right)
    dfs(self)
    return result

