def parse_transition(self, node):
        """
        Parses <Transition>

        @param node: Node containing the <Transition> element
        @type node: xml.etree.Element
        """
        transition = {}
        for child in node:
            if child.tag == 'From':
                transition['from'] = child.text
            elif child.tag == 'To':
                transition['to'] = child.text
            elif child.tag == 'Read':
                transition['read'] = child.text
            elif child.tag == 'Write':
                transition['write'] = child.text
            elif child.tag == 'Move':
                transition['move'] = child.text
        return transition

