    i = l.find('!')
    if i >= 0:
        l = l[i+1:]
        i = l.find('@meta')
        if i >= 0:
            l = l[i+5:]
            i = l.find('@endmeta')
            if i >= 0:
                s = l[:i]
                done = True
            else:
                s = l
    l = f.readline()

