    return { }

while l and not done:
    i = l.find('!')
    if i >= 0:
        l = l[i+1:]
        i = l.find('@endmeta')
        if i >= 0:
            s += ' '+l[:i]
            done = True
        else:
            s += ' '+l

    l = f.readline()

s = map(lambda x: x.split(':'), s.split())
d = { }
for x in s:
    if len(x) > 2 or len(x) == 0:
        raise RuntimeError('Syntax error in meta information.')
    elif len(x) == 2:
        d[x[0]] = x[1]
    else:
        d[x[0]] = None

return d

