def query(self,
              sparql,
              mode="get",
              namespace=None,
              rtn_format="json",
              **kwargs):
        """ runs a sparql query and returns the results

            args:
                sparql: the sparql query to run
                namespace: the namespace to run the sparql query against
                mode: ['get'(default), 'update'] the type of sparql query
                rtn_format: ['json'(default), 'xml'] format of query results
        """
        if mode == "get":
            if rtn_format == "json":
                return self.query_get_json(sparql, namespace, **kwargs)
            elif rtn_format == "xml":
                return self.query_get_xml(sparql, namespace, **kwargs)
            else:
                raise ValueError("Invalid return format")
        elif mode == "update":
            return self.query_update(sparql, namespace, **kwargs)
        else:
            raise ValueError("Invalid query mode")

