mgc_code:
def _jog(self, axis, direction, step):
        """
        Move the pipette on `axis` in `direction` by `step` and update the
        position tracker
        """
        if axis not in ('x', 'y', 'z'):
            raise ValueError("Invalid axis: must be 'x', 'y', or 'z'")
        if direction not in ('forward', 'backward'):
            raise ValueError("Invalid direction: must be 'forward' or 'backward'")
        if not isinstance(step, int) or step <= 0:
            raise ValueError("Invalid step: must be a positive integer")
        if axis == 'x':
            if direction == 'forward':
                self.x_position += step
            else:
                self.x_position -= step
        elif axis == 'y':
            if direction == 'forward':
                self.y_position += step
            else:
                self.y_position -= step
        else:
            if direction == 'forward':
                self.z_position += step
            else:
                self.z_position -= step

