def leastsq_NxN(x, y, fit_offset=False, perc=None):
    if fit_offset:
        x = np.hstack((x, np.ones_like(x)))
    gamma = np.dot(np.linalg.inv(np.dot(x.T, x)), np.dot(x.T, y))
    return gamma

