mgc_code:
def nuc_v(msg):
    """Calculate NUCv, Navigation Uncertainty Category - Velocity (ADS-B version 1)

    Args:
        msg (string): 28 bytes hexadecimal message string,

    Returns:
        int or string: 95% Horizontal Velocity Error
        int or string: 95% Vertical Velocity Error
    """
    if len(msg)!= 56:
        return "Invalid message length"
    msg_bin = bin(int(msg, 16))[2:].zfill(112)
    nuc_v_h = int(msg_bin[8:12], 2)
    nuc_v_v = int(msg_bin[12:16], 2)
    if nuc_v_h == 0:
        h_error = "Not available"
    elif nuc_v_h == 15:
        h_error = "Invalid"
    else:
        h_error = 25 * 2 ** nuc_v_h

    if nuc_v_v == 0:
        v_error = "Not available"
    elif nuc_v_v == 15:
        v_error = "Invalid"
    else:
        v_error = 25 * 2 ** nuc_v_v

    return h_error, v_error

